// Some portions generated by Claude
import assert from "node:assert/strict";
import test from "node:test";
import { blankNodeLabels } from "../../../main/frontend/graph-explorer/blank-labels.ts";
import { mergeTriples } from "../../../main/frontend/graph-explorer/graph-operations.ts";
import { bindingsToTriples } from "../../../main/frontend/graph-explorer/graph-terms.ts";
import { sparqlNodeId } from "../../../main/frontend/graph-explorer/rdf-terms.ts";

const LABEL = "http://www.w3.org/2000/01/rdf-schema#label";
const uri = (value) => ({ type: "uri", value });
const bnode = (value) => ({ type: "bnode", value });
const literal = (value) => ({ type: "literal", value });
const row = (source, predicate, target) => ({ source, predicate: uri(predicate), target });

function labels(rows, extra = {}) {
  let graph = mergeTriples({ nodes: [], edges: [], revision: 0 }, bindingsToTriples(rows));
  graph = { ...graph, nodes: graph.nodes.map((node) => ({ ...node, label: extra[node.id] ?? node.label })) };
  const result = blankNodeLabels(graph, (property) => property === LABEL);
  return Object.fromEntries([...result].map(([id, label]) => [id.replace(/^.*:/, ""), label]));
}

test("a blank node is named by its label, else by what points at it, else by its first value", () => {
  const graph = labels(
    [
      row(bnode("named"), LABEL, literal("Head office")),
      row(uri("urn:bob"), "urn:address", bnode("address")),
      row(bnode("address"), "urn:street", literal("Bryggen 1")),
      row(bnode("lonely"), "urn:role", literal("Engineer")),
      row(bnode("empty"), "urn:p", bnode("other")),
    ],
    { "urn:bob": "Bob" },
  );
  assert.equal(graph.named, "Head office");
  assert.equal(graph.address, "address of Bob");
  assert.equal(graph.lonely, "Engineer");
  assert.equal(graph.other, "Blank node", "only a named resource pointing at it names it");
  assert.equal(graph.empty, "Blank node");
});

test("names are short", () => {
  const long = "x".repeat(200);
  const result = labels([row(bnode("b"), LABEL, literal(long))]);
  assert.ok(result.b.length <= 60);
  assert.ok(result.b.endsWith("…"));
});

test("only blank nodes are named", () => {
  assert.deepEqual(Object.keys(labels([row(uri("urn:a"), "urn:p", uri("urn:b"))])), []);
  assert.ok(sparqlNodeId(bnode("x")).length > 1);
});

import { mergeStatementLinks, statementLinksOf } from "../../../main/frontend/graph-explorer/statement-links.ts";

test("a blank reifier is named after the statement it is about, before its first value", () => {
  const rows = [
    row(uri("urn:alice"), "urn:worksFor", uri("urn:acme")),
    row(bnode("r"), "urn:role", literal("Engineer")),
    {
      source: bnode("r"),
      predicate: uri("http://www.w3.org/1999/02/22-rdf-syntax-ns#reifies"),
      target: { type: "triple", value: { subject: uri("urn:alice"), predicate: uri("urn:worksFor"), object: uri("urn:acme") } },
    },
  ];
  let graph = mergeStatementLinks(mergeTriples({ nodes: [], edges: [], revision: 0 }, bindingsToTriples(rows)), statementLinksOf(rows));
  graph = { ...graph, nodes: graph.nodes.map((node) => ({ ...node, label: { "urn:alice": "Alice", "urn:acme": "Acme" }[node.id] ?? node.label })) };
  const result = blankNodeLabels(graph, (property) => property === LABEL);
  assert.equal([...result.values()][0], "about Alice works for Acme");
});
